-- New isolated schema. Does not change public or the old Supabase instance.
create schema if not exists costpacket;
create table costpacket."user" (id text primary key,name text not null,email text not null unique,email_verified boolean not null default false,image text,created_at timestamp not null default now(),updated_at timestamp not null default now());
create table costpacket.session (id text primary key,expires_at timestamp not null,token text not null unique,created_at timestamp not null default now(),updated_at timestamp not null default now(),ip_address text,user_agent text,user_id text not null references costpacket."user"(id) on delete cascade);
create index session_user_idx on costpacket.session(user_id);
create table costpacket.account (id text primary key,account_id text not null,provider_id text not null,user_id text not null references costpacket."user"(id) on delete cascade,access_token text,refresh_token text,id_token text,access_token_expires_at timestamp,refresh_token_expires_at timestamp,scope text,password text,created_at timestamp not null default now(),updated_at timestamp not null default now());
create index account_user_idx on costpacket.account(user_id);
create table costpacket.verification(id text primary key,identifier text not null,value text not null,expires_at timestamp not null,created_at timestamp not null default now(),updated_at timestamp not null default now());
create index verification_identifier_idx on costpacket.verification(identifier);
create table costpacket.rate_limit(id text primary key,key text not null unique,count integer not null,last_request bigint not null);
create table costpacket.companies(id uuid primary key default gen_random_uuid(),name text not null,owner_id text not null references costpacket."user"(id),created_at timestamptz not null default now());
create table costpacket.users(id text primary key references costpacket."user"(id) on delete cascade,company_id uuid not null references costpacket.companies(id),email text not null,name text not null,role text not null check(role in ('ADMIN','CONTRACTOR','SUBCONTRACTOR')),created_at timestamptz not null default now(),unique(company_id,id));
create index users_company_idx on costpacket.users(company_id);
create table costpacket.projects(id uuid primary key default gen_random_uuid(),company_id uuid not null references costpacket.companies(id),owner_id text not null,name text not null check(length(name) between 1 and 200),description text,budget numeric(12,2) not null default 0 check(budget>=0),status text not null default 'ACTIVE' check(status in ('ACTIVE','ON_HOLD','COMPLETED')),created_at timestamptz not null default now(),unique(company_id,id),foreign key(company_id,owner_id) references costpacket.users(company_id,id));
create index projects_company_idx on costpacket.projects(company_id);
create table costpacket.project_members(id uuid primary key default gen_random_uuid(),company_id uuid not null,project_id uuid not null,user_id text not null,role text,created_at timestamptz not null default now(),unique(project_id,user_id),foreign key(company_id,project_id) references costpacket.projects(company_id,id) on delete cascade,foreign key(company_id,user_id) references costpacket.users(company_id,id));
create table costpacket.tasks(id uuid primary key default gen_random_uuid(),company_id uuid not null,project_id uuid not null,assignee_id text,title text not null check(length(title) between 1 and 200),description text,amount numeric(12,2) not null default 0 check(amount>=0),status text not null default 'PENDING' check(status in ('PENDING','IN_PROGRESS','REVIEW','COMPLETED')),created_at timestamptz not null default now(),unique(company_id,id),foreign key(company_id,project_id) references costpacket.projects(company_id,id) on delete cascade,foreign key(company_id,assignee_id) references costpacket.users(company_id,id));
create index tasks_company_idx on costpacket.tasks(company_id);
create table costpacket.receipts(path text primary key,company_id uuid not null,user_id text not null,mime text not null check(mime in ('image/jpeg','image/png','image/webp')),size numeric not null check(size>0 and size<=10485760),created_at timestamptz not null default now(),foreign key(company_id,user_id) references costpacket.users(company_id,id),unique(company_id,path));
create table costpacket.expenses(id uuid primary key default gen_random_uuid(),company_id uuid not null,description text not null,vendor text,amount numeric(12,2) not null check(amount>0),task_id uuid,receipt_path text,submitted_by_id text not null,status text not null default 'PENDING' check(status in ('PENDING','APPROVED','REJECTED')),created_at timestamptz not null default now(),foreign key(company_id,submitted_by_id) references costpacket.users(company_id,id),foreign key(company_id,task_id) references costpacket.tasks(company_id,id) on delete cascade,foreign key(company_id,receipt_path) references costpacket.receipts(company_id,path));
create index expenses_company_idx on costpacket.expenses(company_id);
create table costpacket.payments(id uuid primary key default gen_random_uuid(),company_id uuid not null,amount numeric(12,2) not null check(amount>0),status text not null default 'PENDING' check(status in ('PENDING','MARKED_PAID','CANCELED')),user_id text not null,task_id uuid not null unique,reference text,note text,paid_at timestamptz,paid_by text,created_at timestamptz not null default now(),foreign key(company_id,user_id) references costpacket.users(company_id,id),foreign key(company_id,task_id) references costpacket.tasks(company_id,id) on delete cascade,foreign key(company_id,paid_by) references costpacket.users(company_id,id));
create index payments_company_idx on costpacket.payments(company_id);
create table costpacket.invites(id uuid primary key default gen_random_uuid(),company_id uuid not null references costpacket.companies(id) on delete cascade,email text not null,role text not null check(role in ('ADMIN','CONTRACTOR','SUBCONTRACTOR')),token_hash text not null unique,invited_by text not null,expires_at timestamptz not null,accepted_at timestamptz,created_at timestamptz not null default now(),foreign key(company_id,invited_by) references costpacket.users(company_id,id));
create index invites_company_idx on costpacket.invites(company_id);
create table costpacket.subscriptions(company_id uuid primary key references costpacket.companies(id) on delete cascade,status text not null,paddle_customer_id text not null,paddle_subscription_id text not null unique,price_id text,current_period_end timestamptz,event_at timestamptz not null,updated_at timestamptz not null default now());
create table costpacket.billing_events(event_id text primary key,event_type text not null,created_at timestamptz not null default now());
